<template>
  <ConsumerShell>
    <ConsumerPageHeader title="成长与荣誉"><router-link class="btn" to="/portal/teams">我的队伍</router-link></ConsumerPageHeader>
    <ConsumerState v-if="loading" loading title="正在读取成长记录"/>
