          <SportsProfileCard :honors="certifiedHonors" :sport-id="sportId"><SportsAvatar :nickname="display.display.nickname" :account-id="display.accountId" :avatar-file-id="display.display.avatar_file_id" :tone="display.display.avatar_style" :title="equippedTitle" :title-code="card?.equipment?.title_code" :points="card?.points" :rank-level="card?.rankIndex" :rank-name="card?.rank"/></SportsProfileCard>
          <p v-if="honorError" class="private-note">认证荣誉暂时无法读取</p>
