          <div v-if="card" class="passport-progress"><div class="progress-next"><span>{{ highest ? '最高段位' : '下一段位 · '+card.nextRank }}</span><strong>{{ highest ? '已达到' : '还差 '+Math.max(0,card.nextThreshold-card.points)+' 分' }}</strong></div><el-progress :percentage="progress" :show-text="false" color="#b39a64"/></div>
          <router-link v-if="!card" class="btn" :to="{path:'/portal/identity',query:{returnTo:'/portal/growth'}}">查看参赛资料</router-link>
