        </section>
        <div class="growth-main">
          <div class="growth-sport-choice"><label for="growth-sport">运动项目</label><el-select id="growth-sport" v-model="sportId" aria-label="选择成长运动" style="width:150px" @change="loadCard"><el-option v-for="sport in sports" :key="sport.id" :value="sport.id" :label="sport.name"/></el-select></div>
          <ConsumerState v-if="cardError" error title="本项目成长记录暂未读取" :description="cardError"><button class="btn" @click="loadCard">重新读取</button></ConsumerState>
          <section v-if="card?.ranks" class="consumer-card rank-directory" aria-label="段位目录"><div class="between"><h2>成长段位</h2><span class="small">{{ card.policyVersion }}</span></div><div class="rank-catalog"><button v-for="step in card.ranks.filter(item=>rankArtworkKey(item.name))" :key="step.index" type="button" :class="['tier-'+rankArtworkKey(step.name),{locked:card.points<step.threshold,current:card.rankIndex===step.index}]" :aria-label="step.name+'，'+step.threshold+'成长分，'+(card.points>=step.threshold?'已达到':'未达到')" @click="rankPreview=step"><SportsRankBadge :rank-name="step.name" size="hero"/><span>{{ step.threshold }} 分</span><small>{{ card.rankIndex===step.index ? '当前段位' : card.points>=step.threshold ? '已达到' : '未达到' }}</small></button></div></section>
          <section class="consumer-card"><h2>我的称号</h2><GrowthTitleGoals :goals="card?.titleGoals"/><div v-if="card?.titles.length" class="title-wall"><button v-for="title in card.titles" :key="title.id"  :class="{equipped:card.equipment?.title_code===title.title_code}" :aria-pressed="card.equipment?.title_code===title.title_code" :disabled="busy" @click="equip(title.title_code)"><SportsTitleBadge :title="title.title" :code="title.title_code"/><small>{{ card.equipment?.title_code===title.title_code ? '正在佩戴' : '佩戴称号' }}</small><em>{{ titleReason(title) }}</em></button></div><div v-else-if="!cardError" class="first-milestone"><h3>暂无称号</h3><p>完成赛事报到或有效比赛后，按成长规则获得。</p><router-link class="btn primary" to="/public/events">查看赛事</router-link></div></section>
