const display=ref<DisplayProfile>(),card=ref<GrowthRankCard>(),sports=ref<{id:string;name:string;code:string}[]>([]),sportId=ref(''),loading=ref(false),busy=ref(false),error=ref(''),celebrate=ref(false),rankPreview=ref<SportsRankStep>();
const form=reactive({nickname:'',avatarStyle:'mint',tagline:'',publicVisible:false});
const cardError=ref('');
const certifiedHonors=ref<CertifiedHonor[]>([]),honorError=ref(false);
let honorRevision=0;
const loadHonorBadge=async()=>{const stamp=++honorRevision;certifiedHonors.value=[];honorError.value=false;if(!sportId.value)return;try{const response=await myCertifiedHonors(sportId.value);if(stamp===honorRevision)certifiedHonors.value=response.data;}catch{if(stamp===honorRevision)honorError.value=true;}};
const tones=[{key:'mint',label:'薄荷',color:'#9dcdb5'},{key:'violet',label:'紫色',color:'#baa5db'},{key:'sun',label:'金色',color:'#dfc37d'},{key:'sky',label:'蓝色',color:'#92bfce'},{key:'coral',label:'珊瑚',color:'#d7aaa0'},{key:'ink',label:'石墨',color:'#6e9684'}];
