let cardRevision=0;
const loadCard=async()=>{const revision=++cardRevision;const badgeTask=loadHonorBadge();cardError.value='';rankPreview.value=undefined;try{const result=(await getGrowthRankCard(sportId.value)).data;if(revision!==cardRevision)return;card.value=result;const key='growth-seen:'+card.value.ownerId+':'+sportId.value,prior=localStorage.getItem(key);celebrate.value=prior!==null&&Number(prior)<card.value.rankIndex;localStorage.setItem(key,String(card.value.rankIndex));}catch(cause){if(revision!==cardRevision)return;card.value=undefined;cardError.value=cause instanceof Error?cause.message:'请检查参赛资料，或稍后重试';}finally{await badgeTask;}};
const load=async()=>{loading.value=true;error.value='';try{display.value=(await getDisplay()).data;const d=display.value.display;Object.assign(form,{nickname:d.nickname,avatarStyle:d.avatar_style,tagline:d.tagline,publicVisible:d.public_visible});sports.value=(await request({url:'/sports/types',headers:{isToken:false}})).data.sports;sportId.value=sportId.value||sports.value.find(s=>s.code==='badminton')?.id||sports.value[0]?.id||'';if(sportId.value)await loadCard();}catch(e){error.value=e instanceof Error?e.message:'请稍后重试';}finally{loading.value=false;}};
