const equip=async(titleCode:string)=>{if(!card.value||busy.value)return;busy.value=true;try{await performAction('growth.equip',{sportId:sportId.value,titleCode,...(card.value.equipment?{expectedVersion:card.value.equipment.version}:{})});await loadCard();ElMessage.success('称号已佩戴');}finally{busy.value=false;}};
const share=async()=>{if(!display.value?.display.public_visible)return;const url=location.origin+'/public/athletes/'+display.value.accountId;try{await navigator.clipboard.writeText(url);ElMessage.success('链接已复制');}catch{window.prompt('复制名片链接',url);}};
const titleReason=(title:{title_code:string;reason:string})=>{try{const source=JSON.parse(title.reason);return `获得时：报到 ${source.checkins||0} 场、完赛 ${source.finishes||0} 场`;}catch{return '参赛记录授予';}};
const milestone=(value:string)=>({checkin:'赛事报到',finish:'有效完赛',team_finish:'小队完赛',correction:'记录更正'})[value]||'成长记录';
onMounted(load);
